import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 11 — How Agents Work","description":"","frontmatter":{"source":"weeks/11-agents/README.md"},"headers":[],"relativePath":"weeks/11-agents/index.md","filePath":"weeks/11-agents/index.md"}'),s={name:"weeks/11-agents/index.md"};function n(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-11--how-agents-work" tabindex="-1">Week 11 — How Agents Work <a class="header-anchor" href="#week-11--how-agents-work" aria-label="Permalink to &quot;Week 11 — How Agents Work&quot;">​</a></h1><blockquote><p>An agent is an LLM in a loop with tools. You decide what it may do; your tests decide whether it worked.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (about 30 min)</td><td>Read this page, your instructor&#39;s reply to your pitch, and rules 3, 4, 7 and 9 of the <a href="./../../setup/safety-contract.html">Safety Contract</a>. Check that your capstone repository exists and that Copilot Chat offers <strong>Agent</strong> (<a href="#before-class">Before class</a>)</td></tr><tr><td><strong>Studio A</strong></td><td>Talk: the agent loop, context, plan first, approvals and sandboxes, how agents fail · <strong>Be the Agent</strong> (30 min, 🔴 AI off) · open your capstone and give it an <code>AGENTS.md</code> with a <strong>Scope</strong> section · checkpoint share</td></tr><tr><td><strong>Studio B</strong></td><td>Show and tell: your first acceptance criterion · live demo · <strong>your first agent-built feature</strong>, test first, with a teach-back · If time: the Copilot CLI, or read a minimal agent loop · exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong></td><td>Default 11:59 pm the night before (AC1 in <code>SPEC.md</code> is due <strong>before Studio B</strong>): first feature on its branch on GitHub, not merged · a trace of your agent&#39;s run · <code>SPEC.md</code> complete · capstone deployed · <code>PROMPTS.md</code> with teach-backs · reflection on Canvas (🔴 AI off)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: Copilot agent mode with approvals on (never autopilot or skip-permissions modes); Ask mode to explain code · 🟡 AI limited: <code>SPEC.md</code> and <code>AGENTS.md</code> (you write them; the AI may critique) · 🔴 AI off: Be the Agent, teach-backs, the trace, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), <a href="./lab.html">Week 11 Lab — Be the Agent, then direct one</a>, <a href="./homework.html">Week 11 Homework — Finish the first feature, complete the spec, deploy</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../projects/capstone.html">Capstone brief</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent/blob/main/README.md" target="_blank" rel="noreferrer">Be the Agent kit</a> · <a href="./../../templates/AGENTS.html">AGENTS.md template</a> · <a href="./../../resources/safe-loop.html">The Safe Loop</a> · <a href="./../../resources/troubleshooting.html#the-agent-broke-or-deleted-things">Troubleshooting: the agent broke or deleted things</a> · <a href="./../../TOOLS.html#credits-budget-for-the-course">Tool Handout: credits</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your first feature, with a test written before the code, is on a branch on GitHub, and your <code>AGENTS.md</code> has a Scope section. Week 12 Studio A merges that branch through your first pull request</td></tr><tr><td><strong>Time</strong></td><td>Studios 2.5 h · outside about 6 h: prep 30 min, homework about 5 h (including project time), <code>PROMPTS.md</code> and the reflection about 30 min</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system: your reflection and submission links go there. Your code, <code>SPEC.md</code>, <code>AGENTS.md</code> and <code>PROMPTS.md</code> stay in your public repository.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Describe an <strong>agent</strong> as a model, tools, a loop and a context window (its working memory), and trace what it does one tool call at a time.</li><li>Ask an agent to plan first, keep approvals on, and run it inside a sandbox with save points before and after.</li><li>Write a short <code>AGENTS.md</code> with a <strong>Scope</strong> section, and explain why it&#39;s advice, not enforcement.</li><li>Recognize how agents fail (fake success, deleted data, publishing what should stay private), using real incidents.</li><li>Build a feature with an agent: the test first, in a separate prompt; red then green in your own terminal; a teach-back before the commit.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your <strong>capstone pitch</strong> is submitted and you&#39;ve read your instructor&#39;s reply (Go, Shrink or Rethink). This week it becomes your <code>SPEC.md</code>.</li><li>☐ Your <strong>capstone repository</strong> exists, created from the starter as part of the pitch milestone, and <code>npm test</code> passes in its Codespace (<a href="./lab.html#before-studio-a-create-your-capstone-repository">how</a>). Pairs: one partner creates it and adds the other as a collaborator.</li><li>☐ Copilot Chat&#39;s mode picker offers <strong>Agent</strong>. Check your credits (the Copilot icon in the status bar): agent work uses them much faster than chat.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>From this week, an AI can edit your files and run commands. Re-read rules <a href="./../../setup/safety-contract.html#3-i-commit-before-and-after-every-agent-task">3</a>, <a href="./../../setup/safety-contract.html#4-i-keep-agents-contained">4</a>, <a href="./../../setup/safety-contract.html#7-i-read-before-i-adopt">7</a> and <a href="./../../setup/safety-contract.html#9-agents-dont-publish-and-untrusted-content-never-shares-a-session-with-my-secrets">9</a> of the Safety Contract. Approvals stay on all week; autopilot and skip-permissions modes are never allowed in this course.</p></div><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-11.html" target="_blank" rel="noreferrer">slides</a>) · <a href="./lab.html#studio-a--be-the-agent-75-min">lab</a>: Be the Agent, open your capstone, <code>AGENTS.md</code> with a Scope section · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · live demo · <a href="./lab.html#studio-b--direct-a-real-agent-75-min">lab</a>: your first agent-built feature · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-11.html" target="_blank" rel="noreferrer">Slides</a>, <a href="./lab.html">lab</a> and <a href="./homework.html">homework</a></li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent/blob/main/README.md" target="_blank" rel="noreferrer">Be the Agent kit</a>: a tiny app with a planted bug, <a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent/blob/main/tool-cards.md" target="_blank" rel="noreferrer">tool cards</a> and <a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent/blob/main/task-card.md" target="_blank" rel="noreferrer">task cards</a></li><li><a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter" target="_blank" rel="noreferrer">Capstone starter</a>: a working app shell with tests, deployment settings and project documents</li><li>Templates: <a href="./../../templates/AGENTS.html">AGENTS.md template</a>, <a href="./../../templates/SPEC.html">SPEC.md template</a>, <a href="./../../templates/PROMPTS.html">PROMPTS.md template</a></li><li>Glossary: <a href="./../../resources/glossary.html#agent">agent</a>, <a href="./../../resources/glossary.html#tool-call">tool call</a>, <a href="./../../resources/glossary.html#harness">harness</a>, <a href="./../../resources/glossary.html#context-window">context window</a>, <a href="./../../resources/glossary.html#agentsmd">Glossary: AGENTS.md</a>, <a href="./../../resources/glossary.html#plan-mode">plan mode</a>, <a href="./../../resources/glossary.html#autopilot-mode">autopilot mode</a>, <a href="./../../resources/glossary.html#sandbox">sandbox</a>, <a href="./../../resources/glossary.html#scoped-token">scoped token</a>, <a href="./../../resources/glossary.html#spending-cap">spending cap</a>, <a href="./../../resources/glossary.html#redgreen-testing">red/green testing</a>, <a href="./../../resources/glossary.html#branch">branch</a></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>.</p><h3 id="an-agent-is-an-llm-in-a-loop-with-tools" tabindex="-1">An agent is an LLM in a loop with tools <a class="header-anchor" href="#an-agent-is-an-llm-in-a-loop-with-tools" aria-label="Permalink to &quot;An agent is an LLM in a loop with tools&quot;">​</a></h3><p>An <strong>agent</strong> has <strong>tools</strong> (list files, read, search, edit, run a command) and works in a <strong>loop</strong>: it chooses a tool call, the <strong>harness</strong> (the program around the model) runs it, the result goes back into its <strong>context</strong>, and it chooses the next step, until it believes the task is done. Everything it knows comes from that context: your prompt, standing instructions and every tool result so far. It never sees your screen. In <strong>Be the Agent</strong> you play both halves of the loop by hand.</p><h3 id="context-is-working-memory" tabindex="-1">Context is working memory <a class="header-anchor" href="#context-is-working-memory" aria-label="Permalink to &quot;Context is working memory&quot;">​</a></h3><p>Everything the agent reads fills its context window, and as it fills, details get squeezed out. So: one task per session, and short standing instructions.</p><h3 id="plan-first-approvals-on-inside-a-sandbox" tabindex="-1">Plan first, approvals on, inside a sandbox <a class="header-anchor" href="#plan-first-approvals-on-inside-a-sandbox" aria-label="Permalink to &quot;Plan first, approvals on, inside a sandbox&quot;">​</a></h3><p>Ask for a plan before any code (&quot;Plan first and wait for my approval&quot;), or pick <strong>Plan</strong> where your tool has it, and edit the plan before you approve it. Agents ask before running commands; you can switch that off. Don&#39;t. Allow each command <strong>once</strong>, after reading it. Run agents in a <strong>sandbox</strong>, where mistakes can&#39;t reach anything you care about: your Codespace holds one project and no personal files. <strong>Commit before and after every agent task</strong>, and push: an agent&#39;s own undo is not a backup.</p><h3 id="how-agents-fail" tabindex="-1">How agents fail <a class="header-anchor" href="#how-agents-fail" aria-label="Permalink to &quot;How agents fail&quot;">​</a></h3><p>In 2026, an agent on a routine test task used a key it found in an unrelated file to delete a company&#39;s production storage, and its backups, in about nine seconds (<a href="./../../resources/case-studies.html#13-pocketos-a-nine-second-database-deletion">case 13</a>); and agents asked to attach screenshots to code reviews put 13,000+ internal screenshots in <strong>public</strong> repositories, with no attacker involved (<a href="./../../resources/case-studies.html#14-pixelleak-agents-publish-13000-screenshots">case 14</a>). Earlier agents deleted a production database and faked the results, or overwrote and wiped a user&#39;s files (<a href="./../../resources/case-studies.html#4-replit-the-deleted-production-database">cases 4</a>, <a href="./../../resources/case-studies.html#5-gemini-cli-files-that-overwrote-each-other">5</a> and <a href="./../../resources/case-studies.html#6-antigravity-clear-the-cache-wipes-a-drive">6</a>).</p><h3 id="agentsmd-is-advice-not-enforcement" tabindex="-1">AGENTS.md is advice, not enforcement <a class="header-anchor" href="#agentsmd-is-advice-not-enforcement" aria-label="Permalink to &quot;AGENTS.md is advice, not enforcement&quot;">​</a></h3><p><code>AGENTS.md</code> is &quot;a README for agents&quot; (<a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a>): what the project is, the commands, what the agent may change (<strong>Scope</strong>), and what it must never do. Keep it short, and read any rules file from the internet before you use it. A scope sentence measurably helps: removing only the scope and consent statement raised one agent&#39;s out-of-scope actions from 0% to 17.1% in 7,500 runs (<a href="https://arxiv.org/pdf/2605.18583" target="_blank" rel="noreferrer">Qu et al.</a>). But the agent <em>reads</em> the file; nothing makes it obey (&quot;context, not enforced configuration&quot;, say <a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">Anthropic&#39;s docs</a>). What actually protects you is outside the agent&#39;s control: the <strong>Codespace</strong>, the <strong>approval prompts</strong> you answer, <strong>scoped keys</strong> that can do only one job (or none within reach), <strong>spending caps</strong> on paid accounts and, from week 13, <strong>database rules</strong>.</p><h3 id="check-first-then-teach-back" tabindex="-1">Check first, then teach back <a class="header-anchor" href="#check-first-then-teach-back" aria-label="Permalink to &quot;Check first, then teach back&quot;">​</a></h3><p>An agent can&#39;t see your app; a test is how it, and you, check the work. Write the test <strong>before</strong> the code, in a <strong>separate prompt</strong>: AI-written tests that come after faulty code tend to agree with it, catching 14% of faults against 25% for tests written independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). Watch it fail (red), then pass (green), in your own terminal. Before you commit, write a 2–3 sentence <strong>teach-back</strong> in <code>PROMPTS.md</code> (<a href="./../../resources/safe-loop.html#teach-back">how</a>), and end the commit message with an <code>Assisted-by:</code> line, required from this week (<a href="./../../resources/safe-loop.html#the-assisted-by-line">how</a>).</p><h3 id="credits-are-a-budget" tabindex="-1">Credits are a budget <a class="header-anchor" href="#credits-are-a-budget" aria-label="Permalink to &quot;Credits are a budget&quot;">​</a></h3><p>Agent sessions make many model calls. On Copilot&#39;s free plans, when the credits run out, agent work stops until the monthly reset (<a href="./../../TOOLS.html#credits-budget-for-the-course">Tool Handout</a>). Small, clear tasks cost less.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li>The week 11 exit ticket (🔴 AI off) at the end of Studio B, including one question about a decision in your week 9 micro-app. Graded on completion, not correctness.</li><li>Only commit code you can explain. In week 12 the feature you build in Studio B becomes your first pull request: you read its whole diff, and a classmate plants a bug in it for you to find with the AI off.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours, including project time. Details and the checklist are in <a href="./homework.html">Week 11 Homework — Finish the first feature, complete the spec, deploy</a>.</p><ul><li><strong>Core:</strong> finish your first feature and publish its branch; trace your agent&#39;s run (🔴 AI off); complete <code>SPEC.md</code>; deploy the capstone; <code>PROMPTS.md</code> with teach-backs; reflection on Canvas.</li><li><strong>Stretch:</strong> read a minimal agent loop; try the Copilot CLI.</li></ul><p>Counts in <a href="./../../assessment/rubrics.html#assignments">Assignments</a>, graded on completion and effort; the capstone has its own <a href="./../../assessment/rubrics.html#capstone">rubric</a>.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Copilot credits ran out</td><td>Switch to the fallback agent in the <a href="./../../TOOLS.html">Tool Handout</a>, or use Ask mode and make the edits yourself. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr><tr><td>No <strong>Agent</strong> option in Copilot Chat</td><td>Check you&#39;re signed in to GitHub in the Codespace and Copilot is enabled. Menus move; the mode picker is at the bottom of the chat box</td></tr><tr><td>Codespaces quota used up</td><td>Stop unused codespaces at github.com/codespaces, or use the optional <a href="./../../setup/local-setup.html">local setup</a> (keep agents away from your personal files)</td></tr><tr><td>Vercel won&#39;t import the capstone</td><td>Personal-account repository only. See <a href="./../../resources/troubleshooting.html#vercel-cant-see-or-import-your-repo">Vercel can&#39;t see or import your repo</a></td></tr><tr><td>No partner for Be the Agent</td><td>The lab has a &quot;Working alone?&quot; option</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>The <a href="https://agents.md/" target="_blank" rel="noreferrer">AGENTS.md</a> open format, with examples from real projects.</li><li>Simon Willison, <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Agentic Engineering Patterns</a> and <a href="https://simonwillison.net/2025/Sep/30/designing-agentic-loops/" target="_blank" rel="noreferrer">Designing agentic loops</a> (why a Codespace is a good sandbox).</li><li>GitHub Docs, <a href="https://docs.github.com/en/copilot/concepts/agents/about-copilot-cli" target="_blank" rel="noreferrer">About GitHub Copilot CLI</a>; VS Code Docs, <a href="https://code.visualstudio.com/docs/agents/run/approvals" target="_blank" rel="noreferrer">Permissions and approvals for agents</a>.</li><li>More readings: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',41)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
